    pushed_from_vector_x(slot_of(k, cont_ds()), 0i64);
    entries_reinstated_x(slot_of(k, cont_rs()), 0i64, delta);
    set(cur(), slot_of(k, cont_cur()));
    set(kk(), fix_val(slot_of(k, cont_k())));
